// TOP BAR
// ═══════════════════════════════════════════════════════════════════

@Composable
private fun SequencerTopBar(
    uiState: SequencerUiState,
    onSelectPattern: (Int) -> Unit,
    onTogglePlay: () -> Unit,
    onToggleRecord: () -> Unit,
    onCopy: () -> Unit,
    onPaste: () -> Unit,
    onClear: () -> Unit,
    onBpmChange: (Float) -> Unit,
    onToggleViewMode: () -> Unit,
    onToggleAutomation: () -> Unit,
    showAutomation: Boolean
) {
    SynthPanel(title = "SEQUENCER", accentColor = KnobAmber) {
        Column(modifier = Modifier.fillMaxWidth()) {
            // Row 1: pattern selector + play/record + actions
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(4.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                // Pattern selector (1–16)
                PatternSelector(
                    selectedId = uiState.selectedPatternId,
                    onSelect = onSelectPattern,
                    modifier = Modifier.weight(1f)
                )

                // Play / Stop
                Box(
                    modifier = Modifier
                        .size(40.dp)
                        .clip(RoundedCornerShape(8.dp))
                        .background(if (uiState.isPlaying) TransportGreen else BgPanel)
                        .border(
                            1.dp,
                            if (uiState.isPlaying) TransportGreen else PanelHighlight.copy(alpha = 0.4f),
                            RoundedCornerShape(8.dp)
                        )
                        .clickable(onClick = onTogglePlay),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        if (uiState.isPlaying) "\u25A0" else "\u25B6",
                        color = Color.White,
                        fontSize = 14.sp,
                        fontWeight = FontWeight.Bold
                    )
                }

                // Record arm
                Box(
                    modifier = Modifier
                        .size(40.dp)
                        .clip(RoundedCornerShape(8.dp))
                        .background(if (uiState.isRecording) TransportRed else BgPanel)
                        .border(
                            1.dp,
                            if (uiState.isRecording) TransportRed else PanelHighlight.copy(alpha = 0.4f),
                            RoundedCornerShape(8.dp)
                        )
                        .clickable(onClick = onToggleRecord),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        "\u25CF",
                        color = if (uiState.isRecording) Color.White else TextSecondary,
                        fontSize = 12.sp,
                        fontWeight = FontWeight.Bold
                    )
                }

                // Copy / Paste / Clear
                Row(horizontalArrangement = Arrangement.spacedBy(2.dp)) {
                    SmallActionButton(label = "C", onClick = onCopy)
                    SmallActionButton(label = "P", onClick = onPaste, enabled = uiState.copyBufferPattern != null)
                    SmallActionButton(label = "X", onClick = onClear)
                }
            }

            Spacer(Modifier.height(4.dp))

            // Row 2: view-mode toggle + BPM
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                // View mode toggle
                Row(horizontalArrangement = Arrangement.spacedBy(2.dp)) {
                    Text(
                        text = "A",
                        color = if (showAutomation) KnobAmber else TextPrimary,
                        fontSize = 10.sp,
                        fontWeight = FontWeight.Bold,
                        modifier = Modifier
                            .background(
                                if (showAutomation) KnobAmber.copy(alpha = 0.4f)
                                else BgPanel.copy(alpha = 0.3f),
                                RoundedCornerShape(4.dp)
                            )
                            .clickable { onToggleAutomation() }
                            .padding(horizontal = 8.dp, vertical = 6.dp)
                    )
                    ViewModeButton(
                        label = "STEP",
                        selected = uiState.viewMode == SequencerViewMode.STEP,
                        onClick = onToggleViewMode
                    )
                    ViewModeButton(
                        label = "PIANO",
                        selected = uiState.viewMode == SequencerViewMode.PIANO_ROLL,
                        onClick = onToggleViewMode
                    )
                }

                // BPM LCD
                LcdDisplay(
                    value = "%.0f".format(uiState.bpm),
                    label = "BPM",
                    color = LcdText,
                    fontSize = 12.sp,
                    modifier = Modifier.width(80.dp)
                )

                // BPM nudge buttons
                Row(horizontalArrangement = Arrangement.spacedBy(2.dp)) {
                    BpmNudgeButton(text = "-") { onBpmChange(uiState.bpm - 1f) }
                    BpmNudgeButton(text = "+") { onBpmChange(uiState.bpm + 1f) }
                }
            }
        }
    }
}

